import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const STATUSES = ['신청', '마감', '마감취소', '승인', '승인취소'];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function toInt(value: unknown, fallback: number): number {
  if (value === undefined || value === null || value === '') {
    return fallback;
  }
  const text = String(value);
  if (!/^\d+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '숫자 형식이 올바르지 않습니다.');
  }
  return Number(text);
}

async function changeStatus(req: Request, from: string, to: string) {
  const id = req.params['execBudgetId'];
  if (typeof id !== 'string' || !/^\d+$/.test(id)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '실행예산 ID가 올바르지 않습니다.');
  }
  return transaction(async (db) => {
    const rows = await db.query(
      'SELECT status AS "status" FROM exec_budget WHERE exec_budget_id = CAST(:id AS bigint)',
      { id },
    );
    if (rows.length === 0) {
      throw new ApiError(404, 'EXEC_BUDGET_NOT_FOUND', '실행예산을 찾을 수 없습니다.');
    }
    if (rows[0].status !== from) {
      throw new ApiError(
        409,
        'EXEC_BUDGET_STATUS_CONFLICT',
        '현재 상태가 ' + rows[0].status + '이어서 처리할 수 없습니다. ' + from + ' 상태에서만 처리할 수 있습니다.',
      );
    }
    await db.execute(
      'UPDATE exec_budget SET status = :to, updated_at = now() WHERE exec_budget_id = CAST(:id AS bigint)',
      { id, to },
    );
    return { status: to };
  });
}

@Controller('api/v1')
export class FnSfr00306Controller {
  @Get('/exec-budgets')
  async listExecBudgets(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const status = query['status'];
    const hasStatus = status !== undefined && status !== null && status !== '';
    if (hasStatus && !STATUSES.includes(String(status))) {
      throw new ApiError(400, 'VALIDATION_FAILED', '상태 값이 올바르지 않습니다.');
    }
    const page = toInt(query['page'], 0);
    const size = Math.min(toInt(query['size'], DEFAULT_SIZE), MAX_SIZE);
    if (size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 크기가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const where = hasStatus ? ' WHERE status = :status' : '';
      const params: Record<string, unknown> = hasStatus ? { status: String(status) } : {};
      const counts = await db.query('SELECT COUNT(*) AS "total" FROM exec_budget' + where, params);
      const items = await db.query(
        'SELECT exec_budget_id AS "execBudgetId", budget_month AS "budgetMonth", amount AS "amount", status AS "status"'
          + ' FROM exec_budget' + where
          + ' ORDER BY exec_budget_id DESC LIMIT :size OFFSET :offset',
        { ...params, size, offset: page * size },
      );
      return { items, page, size, total: Number(counts[0].total) };
    });
  }

  @Post('/exec-budgets/:execBudgetId/close')
  @HttpCode(200)
  async closeExecBudget(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    return changeStatus(req, '신청', '마감');
  }

  @Post('/exec-budgets/:execBudgetId/cancel-close')
  @HttpCode(200)
  async cancelCloseExecBudget(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    return changeStatus(req, '마감', '마감취소');
  }

  @Post('/exec-budgets/:execBudgetId/approve')
  @HttpCode(200)
  async approveExecBudget(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    return changeStatus(req, '마감', '승인');
  }

  @Post('/exec-budgets/:execBudgetId/cancel-approval')
  @HttpCode(200)
  async cancelApprovalExecBudget(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    return changeStatus(req, '승인', '승인취소');
  }
}

