import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Form,
  Field,
  Select,
  Tiles,
  Pairs,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const STATUS_OPTIONS: [string, string][] = [
  ['신청', '신청'],
  ['마감', '마감'],
  ['마감취소', '마감취소'],
  ['승인', '승인'],
  ['승인취소', '승인취소'],
];

const ACTION_LABELS: Record<string, string> = {
  close: '마감',
  cancelClose: '마감취소',
  approve: '승인',
  cancelApproval: '승인취소',
};

interface Action {
  row: Row;
  kind: string;
}

export default function FnSfr00306Page({ role, notify }: PageProps) {
  const [status, setStatus] = useState('');
  const [applied, setApplied] = useState('');
  const [pageNo, setPageNo] = useState(0);
  const [action, setAction] = useState<Action | null>(null);

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/exec-budgets', role, undefined, { status: applied, page: pageNo, size: 20 }),
    [applied, pageNo, role],
  );

  const rows = data ? data.items : [];
  const total = data ? data.total : 0;

  async function run(target: Action) {
    const id = target.row['execBudgetId'];
    if (target.kind === 'close') {
      await call('POST', `/exec-budgets/${id}/close`, role, {});
    } else if (target.kind === 'cancelClose') {
      await call('POST', `/exec-budgets/${id}/cancel-close`, role, {});
    } else if (target.kind === 'approve') {
      await call('POST', `/exec-budgets/${id}/approve`, role, {});
    } else {
      await call('POST', `/exec-budgets/${id}/cancel-approval`, role, {});
    }
    notify(ACTION_LABELS[target.kind] + ' 처리했습니다.');
    setAction(null);
    reload();
  }

  function buttons(row: Row) {
    const current = String(row['status']);
    const kinds: string[] = [];
    if (current === '신청') {
      kinds.push('close');
    }
    if (current === '마감') {
      kinds.push('cancelClose');
      kinds.push('approve');
    }
    if (current === '승인') {
      kinds.push('cancelApproval');
    }
    return (
      <span>
        {kinds.map((kind) => (
          <button key={kind} type="button" onClick={() => setAction({ row, kind })}>
            {ACTION_LABELS[kind]}
          </button>
        ))}
      </span>
    );
  }

  return (
    <div className="bento">
      <section className="box span-8">
        <h2>실행예산 목록</h2>
        <Filters
          onSearch={() => {
            setPageNo(0);
            setApplied(status);
          }}
          onReset={() => {
            setStatus('');
            setApplied('');
            setPageNo(0);
          }}
        >
          <Field label="상태">
            <Select value={status} onChange={setStatus} options={STATUS_OPTIONS} placeholder="전체" />
          </Field>
        </Filters>
        {error ? <ErrorText text={error} /> : null}
        <Band total={total} />
        <DataTable
          rows={rows}
          empty="조회된 실행예산이 없습니다."
          columns={[
            { key: 'execBudgetId', label: '실행예산 ID' },
            { key: 'budgetMonth', label: '편성 월' },
            { key: 'amount', label: '실행예산 금액', render: (r) => <Num value={r['amount']} /> },
            { key: 'status', label: '상태', render: (r) => <Badge value={r['status']} /> },
            { key: 'actions', label: '처리', render: (r) => buttons(r) },
          ]}
        />
        <Pager page={pageNo} size={20} total={total} onPage={setPageNo} />
      </section>
      <section className="box span-4">
        <h2>조회 현황</h2>
        <Tiles
          items={[
            ['조회 건수', <Num value={total} />],
            ['현재 쪽 건수', <Num value={rows.length} />],
          ]}
        />
      </section>
      {action ? (
        <Drawer title={'실행예산 ' + ACTION_LABELS[action.kind]} onClose={() => setAction(null)}>
          <Pairs
            items={[
              ['실행예산 ID', String(action.row['execBudgetId'])],
              ['편성 월', String(action.row['budgetMonth'])],
              ['실행예산 금액', <Num value={action.row['amount']} />],
              ['상태', <Badge value={action.row['status']} />],
            ]}
          />
          <Form
            submit={ACTION_LABELS[action.kind]}
            danger={action.kind === 'cancelClose' || action.kind === 'cancelApproval'}
            note={'이 실행예산을 ' + ACTION_LABELS[action.kind] + ' 처리합니다.'}
            onSubmit={() => run(action)}
          />
        </Drawer>
      ) : null}
    </div>
  );
}
